let parsed: Record<string, Packed> | null = null

function load(): Record<string, Packed> {
  if (!parsed) {
    try {
      parsed = JSON.parse(RAW) as Record<string, Packed>
    } catch {
      parsed = {}
    }
  }
  return parsed
}

/** 查内置词库，没有则返回 null（调用方再决定要不要联网） */
export function offlineDetail(word: string): WordDetail | null {
  const hit = load()[word.trim().toLowerCase()]
  if (!hit || hit[1].length === 0) return null
  return {
    word: word.trim().toLowerCase(),
    phonetic: hit[0] ? `/${hit[0]}/` : '',
    entries: hit[1].map(([pos, ...senses]) => ({ pos: pos || '', senses })),
    synonyms: [],
    antonyms: [],
    sentences: [],
    forms: [],
  }
}
